package codegen

import (
	"encoding/json"
	"fmt"
	"go/format"
	"strconv"
	"strings"

	"github.com/superdurable/dex-connectors-library/schema"
)

// AgentToolsOutputFile is the generated file that offers a connector's
// agent.exposed operations as sdkgo agent tools.
const AgentToolsOutputFile = "zz_generated_agent_tools.go"

// AgentToolsMinimumSDKVersion is the first Connector Go SDK release that
// defines sdkgo.AgentToolMetadata and the agent tool constructors.
const AgentToolsMinimumSDKVersion = "v0.35.0"

// AgentToolOperation is the reviewed agent surface of one exposed operation.
// connectorctl derives it from the manifest and the connector's Go models;
// GenerateAgentTools only renders it.
type AgentToolOperation struct {
	// Operation is the manifest operation; its agent block must expose it.
	Operation schema.Operation
	// ToolName is the connector ID, an underscore, and the snake case operation ID.
	ToolName string
	// Description is the model-facing description: agent.description, else the operation description.
	Description string
	// InputSchema is the JSON Schema 2020-12 object of the operation input,
	// identical to the inputSchema of the language package manifests.
	InputSchema json.RawMessage
}

// ExposedAgentOperations returns the operations whose agent.exposed is true, in manifest order.
func ExposedAgentOperations(manifest schema.Manifest) []schema.Operation {
	var exposed []schema.Operation
	for _, operation := range manifest.Spec.Operations {
		if isAgentExposed(operation) {
			exposed = append(exposed, operation)
		}
	}
	return exposed
}

// GenerateAgentTools renders ExposedAgentTools, Connection.AgentTools,
// Connection.Operations, and Connection.Reference for the exposed operations,
// which must be given in manifest order.
func GenerateAgentTools(manifest schema.Manifest, operations []AgentToolOperation) ([]byte, error) {
	if err := validateAgentToolOperations(manifest, operations); err != nil {
		return nil, err
	}
	generation := &generator{}
	generation.mustWrite("// Code generated by connectorctl generate; DO NOT EDIT.\n")
	generation.mustWrite("// Copyright (c) 2026 Super Durable\n// SPDX-License-Identifier: MIT\n\n")
	generation.mustWrite("package %s\n\n", manifest.Spec.Codegen.Go.Package)
	generation.mustWrite("import (\n\t\"encoding/json\"\n\t\"fmt\"\n\n")
	generation.mustWrite("\t\"github.com/superdurable/dex-connectors-library/sdkgo\"\n)\n\n")

	generation.mustWrite("// ExposedAgentTools returns the reviewed agent metadata of every operation that connector.yaml\n")
	generation.mustWrite("// exposes to agents, in manifest order. Each call returns new metadata values; Branches and\n")
	generation.mustWrite("// StepDefaults are the operation definitions' own and must be treated as read-only.\n")
	generation.mustWrite("func ExposedAgentTools() []sdkgo.AgentToolMetadata {\n\treturn []sdkgo.AgentToolMetadata{\n")
	for _, operation := range operations {
		generation.mustWrite("\t\t%s(),\n", agentToolMetadataFunctionName(operation.Operation))
	}
	generation.mustWrite("\t}\n}\n\n")

	generation.mustWrite("// AgentTools binds every exposed operation to this connection, in ExposedAgentTools order. It\n")
	generation.mustWrite("// works with NewConnectionWithOperations, such as a generated mock package's connection, so an\n")
	generation.mustWrite("// agent host can be tested without a provider. It returns an error for a zero Connection or\n")
	generation.mustWrite("// when an operation's definition does not match its generated metadata.\n")
	generation.mustWrite("func (connection Connection) AgentTools() ([]sdkgo.AgentTool, error) {\n")
	generation.mustWrite("\tif err := connection.validateOperations(); err != nil { return nil, err }\n")
	for _, operation := range operations {
		constructor := "NewQueryAgentTool"
		if operation.Operation.Kind == "mutation" {
			constructor = "NewMutationAgentTool"
		}
		generation.mustWrite("\t%s, err := sdkgo.%s(connection.operations.%s(), connection.reference, %s())\n",
			agentToolVariableName(operation.Operation), constructor, operation.Operation.GoName, agentToolMetadataFunctionName(operation.Operation))
		generation.mustWrite("\tif err != nil { return nil, fmt.Errorf(%q, err) }\n", manifest.Metadata.Name+" agent tool "+operation.Operation.Name+": %w")
	}
	generation.mustWrite("\treturn []sdkgo.AgentTool{")
	for index, operation := range operations {
		if index > 0 {
			generation.mustWrite(", ")
		}
		generation.mustWrite("%s", agentToolVariableName(operation.Operation))
	}
	generation.mustWrite("}, nil\n}\n\n")

	generation.mustWrite("// Operations returns the operations this connection's Step factories and agent tools invoke.\n")
	generation.mustWrite("// It is nil for a zero Connection.\n")
	generation.mustWrite("func (connection Connection) Operations() Operations { return connection.operations }\n\n")
	generation.mustWrite("// Reference returns the connection reference the operations run with.\n")
	generation.mustWrite("func (connection Connection) Reference() sdkgo.ConnectionRef { return connection.reference }\n\n")

	for _, operation := range operations {
		if err := writeAgentToolMetadataFunction(generation, operation); err != nil {
			return nil, err
		}
	}

	formatted, err := format.Source(generation.output.Bytes())
	if err != nil {
		return nil, fmt.Errorf("format generated agent tools: %w\n%s", err, generation.output.String())
	}
	return formatted, nil
}

func validateAgentToolOperations(manifest schema.Manifest, operations []AgentToolOperation) error {
	exposed := ExposedAgentOperations(manifest)
	if len(exposed) == 0 {
		return fmt.Errorf("%s exposes no operation to agents", manifest.Metadata.Name)
	}
	if len(operations) != len(exposed) {
		return fmt.Errorf("%s exposes %d operations to agents, but %d agent tools were given", manifest.Metadata.Name, len(exposed), len(operations))
	}
	for index, operation := range operations {
		if operation.Operation.Name != exposed[index].Name {
			return fmt.Errorf("%s agent tool %d is %q, but the manifest exposes %q there", manifest.Metadata.Name, index, operation.Operation.Name, exposed[index].Name)
		}
		if strings.TrimSpace(operation.ToolName) == "" || strings.TrimSpace(operation.Description) == "" {
			return fmt.Errorf("%s agent tool %s requires a tool name and a description", manifest.Metadata.Name, operation.Operation.Name)
		}
		var inputSchema map[string]json.RawMessage
		if err := json.Unmarshal(operation.InputSchema, &inputSchema); err != nil || inputSchema == nil {
			return fmt.Errorf("%s agent tool %s input schema must be a JSON object", manifest.Metadata.Name, operation.Operation.Name)
		}
		for branchID := range operation.Operation.Agent.Branches {
			if !hasOptionalBranch(operation.Operation, branchID) {
				return fmt.Errorf("%s agent tool %s agent.branches.%s is not an optional branch", manifest.Metadata.Name, operation.Operation.Name, branchID)
			}
		}
	}
	return nil
}

func writeAgentToolMetadataFunction(generation *generator, operation AgentToolOperation) error {
	manifestOperation := operation.Operation
	kind := "sdkgo.AgentOperationKindQuery"
	if manifestOperation.Kind == "mutation" {
		kind = "sdkgo.AgentOperationKindMutation"
	}
	generation.mustWrite("func %s() sdkgo.AgentToolMetadata {\n\treturn sdkgo.AgentToolMetadata{\n", agentToolMetadataFunctionName(manifestOperation))
	generation.mustWrite("\t\tOperation: %sDefinition.Operation,\n", manifestOperation.GoName)
	generation.mustWrite("\t\tKind: %s,\n", kind)
	generation.mustWrite("\t\tToolName: %s,\n", strconv.Quote(operation.ToolName))
	generation.mustWrite("\t\tDescription: %s,\n", strconv.Quote(operation.Description))
	generation.mustWrite("\t\tIsApprovalRecommended: %t,\n", manifestOperation.Agent.Approval == schema.OperationAgentApprovalRecommended)
	generation.mustWrite("\t\tIsRetrySafe: %t,\n", manifestOperation.Agent.Retry == schema.OperationAgentRetrySafe)
	if len(manifestOperation.Agent.Branches) > 0 {
		generation.mustWrite("\t\tBranchOutcomes: map[sdkgo.BranchID]sdkgo.AgentBranchOutcome{\n")
		// Manifest branch order keeps the output deterministic; the agent map has none.
		for _, branch := range manifestOperation.Branches {
			classification, isListed := manifestOperation.Agent.Branches[branch.ID]
			if !isListed {
				continue
			}
			outcome, err := agentBranchOutcomeIdentifier(classification)
			if err != nil {
				return fmt.Errorf("agent tool %s branch %s: %w", manifestOperation.Name, branch.ID, err)
			}
			generation.mustWrite("\t\t\t%sBranch%s: %s,\n", manifestOperation.GoName, branch.GoName, outcome)
		}
		generation.mustWrite("\t\t},\n")
	}
	generation.mustWrite("\t\tInputType: %s,\n", strconv.Quote(manifestOperation.InputType))
	generation.mustWrite("\t\tInputSchema: json.RawMessage(%s),\n", strconv.Quote(string(operation.InputSchema)))
	generation.mustWrite("\t\tBranches: %sDefinition.Branches,\n", manifestOperation.GoName)
	generation.mustWrite("\t\tStepDefaults: %sDefinition.StepDefaults,\n", manifestOperation.GoName)
	generation.mustWrite("\t}\n}\n\n")
	return nil
}

func agentBranchOutcomeIdentifier(classification string) (string, error) {
	switch classification {
	case schema.OperationAgentBranchRejected:
		return "sdkgo.AgentBranchOutcomeRejected", nil
	case schema.OperationAgentBranchUnknown:
		return "sdkgo.AgentBranchOutcomeUnknown", nil
	default:
		return "", fmt.Errorf("outcome %q must be rejected or unknown", classification)
	}
}

func agentToolMetadataFunctionName(operation schema.Operation) string {
	return lowerFirst(operation.GoName) + "AgentToolMetadata"
}

func agentToolVariableName(operation schema.Operation) string {
	return lowerFirst(operation.GoName) + "AgentTool"
}

func isAgentExposed(operation schema.Operation) bool {
	return operation.Agent != nil && operation.Agent.Exposed != nil && *operation.Agent.Exposed
}

func hasOptionalBranch(operation schema.Operation, branchID string) bool {
	for _, branch := range operation.Branches {
		if branch.ID == branchID {
			return branch.Optional
		}
	}
	return false
}
